%%% Types

-doc """
ParallelHash block size in bytes. It is part of the construction and changes the digest.
""".
-type block_size() :: pos_integer().

-doc """
Application-specific domain separation string; the default is empty.
""".
-type customization_string() :: iodata().

-doc """
A canonical 56-byte decaf448 point encoding.
""".
-type decaf448_point() :: <<_:448>>.

-doc """
An immutable native multiplication table for decaf448.
""".
-type decaf448_precomputed() :: erlang:nif_resource().

-doc """
A canonical 56-byte decaf448 scalar encoding.
""".
-type decaf448_scalar() :: <<_:448>>.

-doc """
TurboSHAKE domain byte, defaulting to 16#1F.
""".
-type domain_separation() :: 1..127.

-doc """
Use `no_context` for pure Ed25519, or a context binary of at most 255 bytes.
""".
-type ed25519_context() :: no_context | binary().

-doc """
An immutable native ED25519 keypair resource.
""".
-type ed25519_keypair() :: erlang:nif_resource().

-doc """
A 32-byte ED25519 public key encoding.
""".
-type ed25519_public_key() :: <<_:256>>.

-doc """
A 32-byte ED25519 secret key encoding.
""".
-type ed25519_secret_key() :: <<_:256>>.

-doc """
A 64-byte ED25519 signature encoding.
""".
-type ed25519_signature() :: <<_:512>>.

-doc """
An immutable native ED448 keypair resource.
""".
-type ed448_keypair() :: erlang:nif_resource().

-doc """
A 57-byte ED448 public key encoding.
""".
-type ed448_public_key() :: <<_:456>>.

-doc """
A 57-byte ED448 secret key encoding.
""".
-type ed448_secret_key() :: <<_:456>>.

-doc """
A 114-byte ED448 signature encoding.
""".
-type ed448_signature() :: <<_:912>>.

-doc """
cSHAKE function-name string; the default is empty.
""".
-type function_name() :: iodata().

-doc """
Supported hash algorithm selectors.
""".
-type hash_algorithm() ::
    cshake128
    | cshake256
    | hopmac128
    | hopmac256
    | keccak_224
    | keccak_256
    | keccak_384
    | keccak_512
    | keccakxof_128
    | keccakxof_256
    | kmac128
    | kmac256
    | kt128
    | kt256
    | parallelhash128
    | parallelhash256
    | sha2_512
    | sha3_224
    | sha3_256
    | sha3_384
    | sha3_512
    | shake128
    | shake256
    | tuplehash128
    | tuplehash256
    | turboshake128
    | turboshake256.

-doc """
Algorithm atom or tuple containing initialization parameters in argument order.
""".
-type hash_parameters() ::
    {hopmac128 | hopmac256, output_length(), key()}
    | {hopmac128 | hopmac256, output_length(), key(), customization_string()}
    | {cshake128 | cshake256, output_length()}
    | {cshake128 | cshake256, output_length(), function_name(), customization_string()}
    | keccak_224
    | keccak_256
    | keccak_384
    | keccak_512
    | {keccak_224 | keccak_256 | keccak_384 | keccak_512}
    | {keccak_224 | keccak_256 | keccak_384 | keccak_512 | keccakxof_128 | keccakxof_256, output_length()}
    | {kmac128 | kmac256, output_length(), key()}
    | {kmac128 | kmac256, output_length(), key(), customization_string()}
    | kt128
    | kt256
    | {kt128 | kt256, output_length()}
    | {kt128 | kt256, output_length(), customization_string()}
    | {parallelhash128 | parallelhash256, output_length(), block_size()}
    | {parallelhash128 | parallelhash256, output_length(), block_size(), customization_string()}
    | sha2_512
    | {sha2_512, output_length()}
    | sha3_224
    | sha3_256
    | sha3_384
    | sha3_512
    | {sha3_224 | sha3_256 | sha3_384 | sha3_512 | shake128 | shake256, output_length()}
    | {tuplehash128 | tuplehash256, output_length()}
    | {tuplehash128 | tuplehash256, output_length(), customization_string()}
    | turboshake128
    | turboshake256
    | {turboshake128 | turboshake256, output_length()}
    | {turboshake128 | turboshake256, output_length(), domain_separation()}.

-doc """
An immutable native hash state, with its output length chosen at initialization.
""".
-opaque hash_state() :: erlang:nif_resource().

-doc """
Message bytes accepted as iodata, or one complete TupleHash element during absorption.
""".
-type input() :: iodata().

-doc """
Secret KMAC or HopMAC key material accepted as iodata.
""".
-type key() :: iodata().

-doc """
Requested number of output bytes, including zero.
""".
-type output_length() :: non_neg_integer().

-doc """
