""".
-doc #{group => "Decaf448"}.
-spec decaf448_point_is_valid(Point) -> Result when
    Point :: term(), Result :: boolean().
decaf448_point_is_valid(_Point) ->
    ?nif_stub.

-doc """
Return the additive inverse of `Point` in canonical encoding.

The input point and its negation add to the identity.
An invalid point encoding raises `badarg`.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_point_negate(Point) -> Result when
    Point :: decaf448_point(), Result :: decaf448_point().
decaf448_point_negate(_Point) ->
    ?nif_stub.

-doc """
Return `Scalar * Point` in canonical encoding.

The point must be valid and the scalar must already be canonical.
Invalid operands raise `badarg`; zero and the identity are accepted.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_point_scalarmul(Point, Scalar) -> Result when
    Point :: decaf448_point(), Scalar :: decaf448_scalar(), Result :: decaf448_point().
decaf448_point_scalarmul(_Point, _Scalar) ->
    ?nif_stub.

-doc """
Return the canonical encoding of `Left - Right`.

Both operands must be valid point encodings; otherwise raises `badarg`.
Subtracting a point from itself returns the identity.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_point_sub(Left, Right) -> Result when
    Left :: decaf448_point(), Right :: decaf448_point(), Result :: decaf448_point().
decaf448_point_sub(_Left, _Right) ->
    ?nif_stub.

-doc """
Build an immutable native multiplication table for `Point`.

Reuse the table when multiplying the same point by many scalars.
The resource can be shared between processes and is released automatically
when no references remain. It is specific to Decaf448; invalid points raise `badarg`.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_precompute(Point) -> Result when
    Point :: decaf448_point(), Result :: decaf448_precomputed().
decaf448_precompute(_Point) ->
    ?nif_stub.

-doc """
Multiply the point stored in `Precomputed` by `Scalar`.

The result matches ordinary point-scalar multiplication; the table is unchanged.
A resource from another group, a non-table term, or a noncanonical Decaf448
scalar raises `badarg`.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_precomputed_scalarmul(Precomputed, Scalar) -> Result when
    Precomputed :: decaf448_precomputed(), Scalar :: decaf448_scalar(), Result :: decaf448_point().
decaf448_precomputed_scalarmul(_Precomputed, _Scalar) ->
    ?nif_stub.

-doc """
Return `(Left + Right) mod l`, where `l` is the group order.

Both operands must already be canonical scalars; otherwise raises `badarg`.
The result is canonically encoded.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_scalar_add(Left, Right) -> Result when
    Left :: decaf448_scalar(), Right :: decaf448_scalar(), Result :: decaf448_scalar().
decaf448_scalar_add(_Left, _Right) ->
    ?nif_stub.

-doc """
Divide `Scalar` by two modulo the group order.

This is multiplication by the modular inverse of two, rather than integer
division. Adding the result to itself recovers the input, including for odd
scalars. A noncanonical scalar raises `badarg`.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_scalar_halve(Scalar) -> Result when
    Scalar :: decaf448_scalar(), Result :: decaf448_scalar().
decaf448_scalar_halve(_Scalar) ->
    ?nif_stub.

-doc """
Return the multiplicative inverse of `Scalar` modulo the group order.

Multiplying a nonzero scalar by its inverse gives the canonical scalar one.
Zero has no inverse and returns `error`. Noncanonical scalars raise `badarg`.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_scalar_invert(Scalar) -> Result when
    Scalar :: decaf448_scalar(), Result :: decaf448_scalar() | error.
decaf448_scalar_invert(_Scalar) ->
    ?nif_stub.

-doc """
Return whether `Scalar` is a canonical 56-byte little-endian scalar.

Its integer value must be smaller than the group order; zero is accepted.
Wrong-sized binaries, out-of-range values, and non-binaries return `false`.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_scalar_is_canonical(Scalar) -> Result when
    Scalar :: term(), Result :: boolean().
decaf448_scalar_is_canonical(_Scalar) ->
    ?nif_stub.

-doc """
Return `(Left * Right) mod l`, where `l` is the group order.

Both operands must already be canonical scalars; otherwise raises `badarg`.
The result is canonically encoded.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_scalar_mul(Left, Right) -> Result when
    Left :: decaf448_scalar(), Right :: decaf448_scalar(), Result :: decaf448_scalar().
decaf448_scalar_mul(_Left, _Right) ->
    ?nif_stub.

-doc """
Return `-Scalar mod l`, where `l` is the group order.

The result adds to the input to give zero; zero is its own negation.
A noncanonical scalar raises `badarg`.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_scalar_negate(Scalar) -> Result when
    Scalar :: decaf448_scalar(), Result :: decaf448_scalar().
decaf448_scalar_negate(_Scalar) ->
    ?nif_stub.

-doc """
Reduce an arbitrary-length unsigned little-endian integer modulo the group order.

Returns a canonical 56-byte scalar. Leading zero bytes at the
most-significant end are allowed, and the empty binary reduces to zero.
This operation does not hash or clamp its input. Non-binaries raise `badarg`.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_scalar_reduce(Bytes) -> Result when
    Bytes :: binary(), Result :: decaf448_scalar().
decaf448_scalar_reduce(_Bytes) ->
    ?nif_stub.

-doc """
Return `(Left - Right) mod l`, where `l` is the group order.

Both operands must already be canonical scalars; otherwise raises `badarg`.
A negative difference wraps modulo `l` and the result is canonically encoded.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_scalar_sub(Left, Right) -> Result when
    Left :: decaf448_scalar(), Right :: decaf448_scalar(), Result :: decaf448_scalar().
decaf448_scalar_sub(_Left, _Right) ->
    ?nif_stub.

